// ZIP stored entries: PNG is already compressed. UTF-8 names, CRC32 and ZIP32 bounds.
const BatchZip=(()=>{
const table=Array.from({length:256},(_,n)=>{for(let i=0;i<8;i++)n=n&1?0xedb88320^(n>>>1):n>>>1;return n>>>0});
function crc(bytes){let c=0xffffffff;for(let b of bytes)c=table[(c^b)&255]^(c>>>8);return (c^0xffffffff)>>>0}
function header(size){let bytes=new Uint8Array(size),v=new DataView(bytes.buffer);return {bytes,u16:(o,n)=>v.setUint16(o,n,true),u32:(o,n)=>v.setUint32(o,n,true)}}
async function create(entries){let parts=[],central=[],offset=0;for(let e of entries){let name=new TextEncoder().encode(e.name),data=new Uint8Array(await e.blob.arrayBuffer()),checksum=crc(data);if(name.length>65535||offset+data.length>0xffffffff)throw Error('Batch exceeds ZIP size limits. Download fewer photos.');let h=header(30);h.u32(0,0x04034b50);h.u16(4,20);h.u16(6,0x800);h.u16(12,33);h.u32(14,checksum);h.u32(18,data.length);h.u32(22,data.length);h.u16(26,name.length);parts.push(h.bytes,name,e.blob);let c=header(46);c.u32(0,0x02014b50);c.u16(4,20);c.u16(6,20);c.u16(8,0x800);c.u16(14,33);c.u32(16,checksum);c.u32(20,data.length);c.u32(24,data.length);c.u16(28,name.length);c.u32(42,offset);central.push(c.bytes,name);offset+=30+name.length+data.length}let length=central.reduce((s,b)=>s+b.length,0),end=header(22);end.u32(0,0x06054b50);end.u16(8,entries.length);end.u16(10,entries.length);end.u32(12,length);end.u32(16,offset);return new Blob([...parts,...central,end.bytes],{type:'application/zip'})}return {create};})();
